const message = $('Telegram Trigger').item.json.message;
const userCaption = message.caption || "Insane Minecraft build hacks, secrets, and clutch moments";

const prompt = `You are an elite Minecraft gaming YouTuber creating viral YouTube Shorts.
Topic/Context: "${userCaption}"

Create:
1. "title": A viral, high-CTR hook title strictly under 60 characters with emojis ending with "#Shorts #Minecraft" (e.g. "Illegal Minecraft Build Hack! ⛏️ #Shorts #Minecraft" or "Bro Escaped With Half a Heart?! 😱 #Shorts #Minecraft").
2. "description": An exciting, suspenseful 2-sentence caption followed by viral hashtags: #Minecraft #MinecraftShorts #MinecraftBuilds #MinecraftMemes #Shorts #Gaming #Viral.
3. "tags": 6-10 comma-separated keywords (e.g. "minecraft, minecraft shorts, minecraft builds, minecraft memes, mcpe, minecraft secrets, gaming, viral").

Respond strictly in valid JSON only with NO markdown and NO extra text:
{
  "title": "Your Title Here #Shorts #Minecraft",
  "description": "Your description here...\\n\\n#Minecraft #MinecraftShorts #MinecraftBuilds #MinecraftMemes #Shorts #Gaming #Viral",
  "tags": "minecraft, minecraft shorts, minecraft builds, minecraft memes, mcpe, gaming"
}`;

return {
  prompt: prompt,
  userCaption: userCaption,
  chatId: message.chat.id,
  messageId: message.message_id
};

let raw = $json.response;
let meta = {
  title: "Epic Minecraft Secret! ⛏️ #Shorts #Minecraft",
  description: "Can you believe this secret trick?! Try this in your survival world! #Minecraft #MinecraftShorts #MinecraftBuilds #MinecraftMemes #Shorts #Gaming #Viral",
  tags: "minecraft, minecraft shorts, minecraft builds, gaming"
};

try {
  const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
  if (parsed.title) meta.title = parsed.title;
  if (parsed.description) meta.description = parsed.description;
  if (parsed.tags) {
    meta.tags = Array.isArray(parsed.tags) ? parsed.tags.join(',') : String(parsed.tags);
  }
} catch(e) {
  meta.description = raw;
}

if (!meta.title.toLowerCase().includes('#shorts')) {
  meta.title = `${meta.title.slice(0, 48)} #Shorts`;
}
if (!meta.title.toLowerCase().includes('#minecraft')) {
  meta.title = `${meta.title} #Minecraft`;
}

if (Array.isArray(meta.tags)) {
  meta.tags = meta.tags.join(',');
}

const binary = $('Download Telegram Video').item.binary;

return {
  json: {
    title: meta.title,
    description: meta.description,
    tags: String(meta.tags),
    chatId: $('Prepare Minecraft Prompt').item.json.chatId
  },
  binary: binary
};

